  const verifyPasscodeAction = (modules, action, callback, name = 'Action') => {
    const permissions = getStaffPermissions();
    if (!permissions) {
      setPasscodeModalState({
        isOpen: true,
        requiredModules: modules,
        actionKey: action,
        onSuccess: callback,
        actionName: name
      });
      return;
    }

    let hasDirectPermission = false;
    for (const mod of modules) {
      if (permissions.pos_access?.[mod]?.[action] === true) {
        hasDirectPermission = true;
        break;
      }
    }

    if (hasDirectPermission) {
      callback();
      return;
    }

    let passcodeAllowed = false;
    for (const mod of modules) {
      if (permissions.pos_access?.[mod]?.[action + '_passcode'] === true) {
        passcodeAllowed = true;
        break;
      }
    }

    if (!passcodeAllowed) {
      toast.error(`Access Denied: You do not have permission to perform '${name}'`);
      return;
    }

    setPasscodeModalState({
      isOpen: true,
      requiredModules: modules,
      actionKey: action,
      onSuccess: callback,
      actionName: name
    });
